{
  "implementation": "def solve(case):
    lines = case.get("lines", [])
    trajectory = []
    state = "START"
    error_line = None
    valid = True
    for i, line in enumerate(lines):
        line_num = i + 1
        content = ""
        typ = None
        if line.startswith("Thought:"):
            typ = "thought"
            content = line[8:].strip()
        elif line.startswith("Action:"):
            typ = "action"
            content = line[7:].strip()
        elif line.startswith("Observation:"):
            typ = "observation"
            content = line[12:].strip()
        elif line.startswith("Final:"):
            typ = "final"
            content = line[6:].strip()
        else:
            error_line = line_num
            valid = False
            break

        if state == "START":
            if typ != "thought":
                error_line = line_num
                valid = False
                break
            state = "after_thought"
        elif state == "after_thought":
            if typ == "action":
                state = "after_action"
            elif typ == "final":
                state = "after_final"
            else:
                error_line = line_num
                valid = False
                break
        elif state == "after_action":
            if typ != "observation":
                error_line = line_num
                valid = False
                break
            state = "after_observation"
        elif state == "after_observation":
            if typ != "thought":
                error_line = line_num
                valid = False
                break
            state = "after_thought"
        elif state == "after_final":
            error_line = line_num
            valid = False
            break
        else:
            raise ValueError("Unexpected state")

        if not valid:
            break

        trajectory.append({"type": typ, "content": content})

    if valid:
        if state != "after_final":
            error_line = len(lines)
            valid = False
        else:
            error_line = None

    return {"error_line": error_line, "trajectory": trajectory, "valid": valid}
